<?php
namespace App\Commands\Chat; use App\Commands\SafeBaseCommand; use App\Commands\Support\SubsCommandTrait;
class Audit extends SafeBaseCommand { use SubsCommandTrait; protected $group='Chat'; protected $name='chat:audit'; protected $description='Chat audit'; protected $options=['--json'=>'JSON']; public function run(array $params){$this->parseParams($params);$issues=[];foreach(['chat/server.js','chat/bin/chat-start-safe.sh','chat/bin/chat-stop-safe.sh'] as $f){if(!is_file(ROOTPATH.$f)){$issues[]="Missing {$f}";}} $report=['status'=>empty($issues)?'ok':'degraded','issues'=>$issues,'chat'=>$this->mgr()->status('chat.app')];$report['report']=$this->writeDoc('audits','chat-audit-'.date('Y-m-d').'.json',$report);$this->emit($report,$this->optBool('json'));return empty($issues)?EXIT_SUCCESS:EXIT_ERROR;}}
